def sym(i,tex,meaning,unit,domain,shape='scalar'):
    return {'id':i,'latex':tex,'meaning':meaning,'unit':unit,'domain':domain,'shape':shape,'first_definition':'notation section'}
def eq(i,tex,syms,assumptions,meaning,dim,requirements=None):
    return {'id':i,'latex':tex,'symbol_ids':syms,'assumption_ids':assumptions,'meaning':meaning,'lhs_dimension':dim,'rhs_dimension':dim,'required_symbol_units':requirements or {},'evidence_type':'project_derivation'}
def deriv(i,conditions,eqs,steps,status='derived'):
    return {'id':i,'conditions':conditions,'equation_ids':eqs,'steps':steps,'status':status,'open_gaps':[]}
