for name in ['bench-dragon','resource']:
    d=json.loads((OUT/f'math/{name}-dossier.json').read_text(encoding='utf-8'))
    tex=['% A+ reusable source. Not yet compiled; C+ owns real compilation/rendering.','% Units use SI conventions; radians dimensionless. Requires amsmath, amssymb, amsthm.','\\subsection*{Notation}',r'\begin{tabular}{llll}',r'Symbol & Meaning & Unit & Domain \\']
    # Plain English domain strings in monospaced text escaped for table safety.
    escape=lambda x:x.replace('\\',r'\textbackslash{}').replace('_',r'\_').replace('&',r'\&').replace('%',r'\%').replace('{',r'\{').replace('}',r'\}')
    for s in d['symbols']:tex.append('$'+s['latex']+'$ & '+escape(s['meaning'])+' & '+escape(s['unit'])+' & '+escape(s['domain'])+r' \\')
    tex += [r'\end{tabular}',r'\subsection*{Assumptions}']
    for a in d['assumptions']:tex.append('\\paragraph{'+a['id']+'} '+escape(a['statement']))
    tex.append(r'\subsection*{Equations}')
    for e in d['equations']:tex += ['% '+e['meaning'],r'\begin{equation}',e['latex'],r'\label{'+e['id']+'}',r'\end{equation}']
    for item in d['derivations']+d['propositions']:
        tex += ['\\paragraph{'+item['id']+'}', 'Conditions: '+escape('; '.join(item['conditions']))+'.',r'\begin{enumerate}']
        tex += [r'\item '+escape(step) for step in item['steps']];tex.append(r'\end{enumerate}')
    (OUT/f'math/{name}-fragments.tex').write_text('\n'.join(tex)+'\n',encoding='utf-8')
